    count_b = Counter(b)

    for num in sorted(count_a.keys()):
        while count_a[num] > 0:
            if count_b[num] > 0:
                count_b[num] -= 1
                count_a[num] -= 1
            elif num % 2 == 0 and count_b[num // 2] > 0:
                count_b[num // 2] -= 1
                count_a[num] -= 1
            else:
                current = num
